package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class MigrationRowsAcceptance {
 static String seed(Store store)throws Exception{try(var db=store.open()){String actor=PlatformFoundationTest.bind(db);var plan=TransferValidationAcceptance.basic();plan.put("history",true);plan.put("attachments",true);String id=TransferJobs.create(db,plan,actor,store.migrationOrigins).get("job_id").toString();for(int n=1;n<=3;n++)db.update("INSERT INTO os_transfer_item(job_id,source_table,source_id,data,content) VALUES(?,?,?,?,?)",id,"incident",MigrationSource.key(n),JSON.writeValueAsString(MigrationConflictsAcceptance.row(n,"Retained <script>"+n)),null);db.update("INSERT INTO os_transfer_item(job_id,source_table,source_id,data,content) VALUES(?,?,?,?,?)",id,"sys_attachment",MigrationSource.key(4),JSON.writeValueAsString(map("sys_id",MigrationSource.key(4),"file_name","safe.txt","size_bytes","3")),"abc".getBytes());db.connection.commit();return id;}}
 static String api(String id){return TransferAcceptance.API+"/"+id+"/rows";}
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> r)throws Exception{return TransferAcceptance.result(r,200);}
 static void run(WorkflowSupport h)throws Exception{
  h.account("StageReader","reader");String id=seed(h.store),root=api(id),detail=root+"/incident/"+MigrationSource.key(1);long count;try(var db=h.store.open()){count=db.count("SELECT COUNT(*) FROM os_record");}var list=result(h.get(root+"?limit=1",auth("admin")));assertEquals(3,((Number)list.get("total")).intValue());assertEquals(1,list.get("next_offset"));assertEquals(MigrationSource.key(1),objects(list.get("rows")).getFirst().get("source_id"));assertEquals(2,objects(result(h.get(root+"?limit=2&offset=1",auth("admin"))).get("rows")).size());assertEquals(-1,result(h.get(root+"?offset=10000",auth("admin"))).get("next_offset"));assertEquals("fetching",list.get("state"));var row=result(h.get(detail,auth("admin")));assertEquals("Retained <script>1",object(row.get("source")).get("short_description"));assertEquals("Retained <script>1",object(row.get("mapped")).get("short_description"));assertEquals("",row.get("validation_error"));assertEquals("",row.get("attachment_sha256"));
  var file=result(h.get(root+"/sys_attachment/"+MigrationSource.key(4),auth("admin")));assertNull(file.get("mapping"));assertEquals(3,file.get("attachment_bytes"));assertEquals(org.apache.commons.codec.digest.DigestUtils.sha256Hex("abc"),file.get("attachment_sha256"));assertFalse(file.containsKey("content"));assertEquals(1,objects(result(h.get(root+"?source_table=sys_attachment",auth("admin"))).get("rows")).size());assertEquals(0,objects(result(h.get(root+"?source_table=sys_audit",auth("admin"))).get("rows")).size());
  assertEquals(401,h.get(root,null).statusCode());for(String path:List.of(root,detail))assertEquals(403,h.get(path,auth("StageReader")).statusCode());assertEquals(405,h.json("POST",root,map(),auth("admin")).statusCode());assertEquals(405,h.json("POST",detail,map(),auth("admin")).statusCode());for(String query:List.of("?source_table=unknown","?limit=0","?limit=101","?offset=-1","?extra=x","?limit=1&limit=2"))assertEquals(400,h.get(root+query,auth("admin")).statusCode());assertEquals(400,h.get(detail+"?extra=x",auth("admin")).statusCode());assertEquals(400,h.get(root+"/unknown/"+MigrationSource.key(1),auth("admin")).statusCode());assertEquals(404,h.get(root+"/incident/"+id(),auth("admin")).statusCode());assertEquals(404,h.get(api(id()),auth("admin")).statusCode());
  Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"incident");var denied=new LinkedHashMap<>(schema);denied.put("record_roles",map("read",List.of("agent")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(denied));db.connection.commit();}try{assertEquals(403,h.get(root,auth("admin")).statusCode());assertEquals(403,h.get(detail,auth("admin")).statusCode());}finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(schema));db.connection.commit();}}
  try(var db=h.store.open()){var bad=MigrationConflictsAcceptance.row(1,"Invalid mapped field");bad.put("priority","invalid");db.update("UPDATE os_transfer_item SET data="+db.jsonParameter()+" WHERE job_id=? AND source_table='incident' AND source_id=?",JSON.writeValueAsString(bad),id,MigrationSource.key(1));db.connection.commit();}assertFalse(result(h.get(detail,auth("admin"))).get("validation_error").toString().isBlank());new Store(h.environment);assertEquals(3,((Number)result(h.get(root,auth("admin"))).get("total")).intValue());try(var db=h.store.open()){assertEquals(count,db.count("SELECT COUNT(*) FROM os_record"));PlatformFoundationTest.bind(db);MigrationStops.cancel(db,id,map("reason","Inspection complete"));db.connection.commit();}assertEquals("cancelled",result(h.get(root,auth("admin"))).get("state"));assertEquals(200,h.get(detail,auth("admin")).statusCode());
 }
}
